        "id": "pequena-historia-das-grandes-nacoes-japao",
        "title": "Pequena História das Grandes Nações – Japão",
        "author": "Otto Zierer",
        "publisher": "Círculo do Livro S. A.",
        "collection": "Círculo do Livro S. A. • Coleção",
        "year": 1985,
        "pages": 124,
        "genre": "História",
        "time": "~ 2h 16m",
